import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { cause3Schema, type Cause3 } from "./cause3.js";

export type ContinueAsNewWorkflowExecutionFailedEventAttributes = {
  /**
   * The cause of the failure. This information is generated by the system and can be useful for
   * diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it
   * lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage
   * Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
   */
  cause: Cause3;
  /**
   * The ID of the DecisionTaskCompleted event corresponding to the decision task that resulted in
   * the ContinueAsNewWorkflowExecution decision that started this execution. This information can
   * be useful for diagnosing problems by tracing back the chain of events leading up to this event.
   */
  decisionTaskCompletedEventId: number;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const continueAsNewWorkflowExecutionFailedEventAttributesSchema: Schema<ContinueAsNewWorkflowExecutionFailedEventAttributes> =
  s.object<ContinueAsNewWorkflowExecutionFailedEventAttributes>(
    {
      cause: cause3Schema,
      decisionTaskCompletedEventId: s.int(),
    },
    { additionalProperties: s.json() },
  );
